<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import CdmButton from './CdmButton.vue'
const props=defineProps({title:{type:String,required:true},description:String,busy:Boolean,wide:Boolean,closeOnBackdrop:{type:Boolean,default:true}})
const emit=defineEmits(['close'])
const dialog=ref(null);let trigger,previousOverflow
const controls=()=>Array.from(dialog.value?.querySelectorAll?.('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')||[]).filter(item=>item.getClientRects().length)
function close(){if(!props.busy)emit('close')}
function keydown(event){if(event.key==='Escape'){event.preventDefault();close();return}if(event.key!=='Tab')return;const items=controls(),first=items[0],last=items.at(-1);if(!first){event.preventDefault();dialog.value?.focus();return}if(event.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===dialog.value)){event.preventDefault();first.focus()}}
onMounted(async()=>{trigger=document.activeElement;previousOverflow=document.body?.style?.overflow;if(document.body?.style)document.body.style.overflow='hidden';await nextTick();dialog.value?.focus()})
onBeforeUnmount(()=>{if(document.body?.style&&previousOverflow!==undefined)document.body.style.overflow=previousOverflow;if(trigger?.isConnected&&!trigger.disabled)trigger.focus?.({preventScroll:true})})
</script>
<template><Teleport to="body"><div class="cdm-dialog-backdrop" @mousedown.self="closeOnBackdrop&&close()"><section ref="dialog" class="cdm-dialog" :class="{'cdm-dialog--wide':wide}" role="dialog" aria-modal="true" :aria-labelledby="`${$attrs.id||'cdm-dialog'}-title`" :aria-describedby="description?`${$attrs.id||'cdm-dialog'}-description`:undefined" :aria-busy="busy||undefined" tabindex="-1" @keydown="keydown"><header><div><h2 :id="`${$attrs.id||'cdm-dialog'}-title`">{{title}}</h2><p v-if="description" :id="`${$attrs.id||'cdm-dialog'}-description`">{{description}}</p></div><CdmButton variant="ghost" size="icon" aria-label="Close dialog" :disabled="busy" @click="close">×</CdmButton></header><div class="cdm-dialog__content"><slot /></div><footer v-if="$slots.footer"><slot name="footer" /></footer></section></div></Teleport></template>
<style scoped>.cdm-dialog-backdrop{position:fixed;inset:0;z-index:1800;display:grid;place-items:center;padding:20px;background:rgb(3 17 11 / 64%)}.cdm-dialog{width:min(540px,100%);max-height:min(90dvh,900px);overflow:auto;border:1px solid var(--cdm-border);border-radius:var(--cdm-radius-lg);background:var(--cdm-surface-elevated);color:var(--cdm-text);box-shadow:var(--cdm-shadow-md);font-family:var(--cdm-font-sans)}.cdm-dialog--wide{width:min(900px,100%)}.cdm-dialog>header{position:sticky;top:0;z-index:1;display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid var(--cdm-border);background:var(--cdm-surface-muted)}.cdm-dialog h2{margin:0;font-size:18px}.cdm-dialog header p{margin:4px 0 0;color:var(--cdm-text-muted);font-size:12px;line-height:1.45}.cdm-dialog__content{padding:20px}.cdm-dialog>footer{display:flex;justify-content:flex-end;gap:8px;padding:13px 20px;border-top:1px solid var(--cdm-border);background:var(--cdm-surface-muted)}.cdm-dialog:focus-visible{outline:2px solid var(--cdm-focus);outline-offset:2px}@media(max-width:600px){.cdm-dialog-backdrop{padding:8px}.cdm-dialog{max-height:96dvh}.cdm-dialog>header,.cdm-dialog__content{padding:16px}.cdm-dialog>footer{padding:12px 16px}}</style>
